function escapeHtml(s){
  return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function formatDate(d){
  const dt = new Date(d);
  return `${dt.getMonth()+1}月${dt.getDate()}日`;
}

