function computeStreak(records){
  if(records.length===0) return 0;
  const days = new Set(records.map(r=>new Date(r.learnDate).toDateString()));
  let streak=0;
  const d = new Date(); d.setHours(0,0,0,0);
  // 如果今天没有记录，从昨天开始算
  if(!days.has(d.toDateString())) d.setDate(d.getDate()-1);
  while(days.has(d.toDateString())){
    streak++;
    d.setDate(d.getDate()-1);
  }
  return streak;
}

async function computeReviewTasks(records){
  const mode = MODES[currentMode];
  const tasks = [];
  
  if(mode.isErrorMode){
    // 仅错题复习模式：返回所有错题作为复习任务
    const wrongQs = (await dbGetAll('wrongQuestions')).filter(w=>w.userId===currentUserId);
    wrongQs.forEach(w=>{
      tasks.push({ qid:w.questionId, title:w.title, subject:w.subject, chapter:w.chapter, label:`错${w.wrongCount}次`, node:0, overdue:false, isErrorReview:true });
    });
    return tasks;
  }
  
  // 极简模式：按时间节点计算
  const byQuestion = {};
  records.forEach(r=>{
    if(!byQuestion[r.questionId]) byQuestion[r.questionId] = { title:r.title, subject:r.subject, chapter:r.chapter, dates:[] };
    byQuestion[r.questionId].dates.push(new Date(r.learnDate));
  });
  const today = new Date(); today.setHours(0,0,0,0);
  Object.entries(byQuestion).forEach(([qid,data])=>{
    const firstLearn = new Date(Math.min(...data.dates.map(d=>d.getTime())));
    firstLearn.setHours(0,0,0,0);
    for(let i=0;i<mode.nodes.length;i++){
      const reviewDate = new Date(firstLearn);
      reviewDate.setDate(reviewDate.getDate()+mode.nodes[i]);
      const reviewed = data.dates.some(d=>{ const dd=new Date(d); dd.setHours(0,0,0,0); return dd.getTime()>=reviewDate.getTime(); });
      if(!reviewed && reviewDate<=today){
        tasks.push({ qid, title:data.title, subject:data.subject, chapter:data.chapter, label:`第${mode.nodes[i]}天`, node:mode.nodes[i], overdue: reviewDate<today });
        break;
      }
    }
  });
  tasks.sort((a,b)=>(b.overdue?1:0)-(a.overdue?1:0));
  return tasks;
}

function computeWeakPoints(records){
  const byChapter = {};
  records.forEach(r=>{
    const key = r.chapter;
    if(!byChapter[key]) byChapter[key] = { chapter:r.chapter, subject:r.subject, total:0, correct:0 };
    byChapter[key].total++;
    if(r.correct) byChapter[key].correct++;
  });
  return Object.values(byChapter)
    .map(c=>({...c, accuracy:c.total>0?Math.round(c.correct/c.total*100):0}))
    .sort((a,b)=>a.accuracy-b.accuracy)
    .slice(0,3);
}

function computeSubjectProgress(records){
  const result = [];
  Object.entries(SUBJECTS).forEach(([key,sub])=>{
    const subRecords = records.filter(r=>r.subject===key);
    const doneSet = new Set(subRecords.map(r=>r.questionId));
    const totalQuestions = allQuestions.filter(q=>q.subject===key).length;
    const correct = subRecords.filter(r=>r.correct).length;
    const accuracy = subRecords.length>0 ? Math.round(correct/subRecords.length*100) : 0;
    result.push({ key, name:sub.name, icon:sub.icon, done:doneSet.size, total:totalQuestions, accuracy });
  });
  return result;
}

function computeHeatmap(records){
  const days = [];
  const today = new Date(); today.setHours(0,0,0,0);
  for(let i=13;i>=0;i--){
    const d = new Date(today); d.setDate(d.getDate()-i);
    const count = records.filter(r=>new Date(r.learnDate).toDateString()===d.toDateString()).length;
    days.push({ date:d, count });
  }
  return days;
}

function selectMode(mode){
  currentMode = mode;
  saveUserSetting('mode', mode);
  // 更新模式选择器UI
  document.querySelectorAll('.mode-card').forEach((card,i)=>{
    const keys = Object.keys(MODES);
    card.classList.toggle('active', keys[i]===mode);
    const badge = card.querySelector('.mc-badge');
    if(keys[i]===mode && !badge){
      const b=document.createElement('div'); b.className='mc-badge'; b.textContent='当前'; card.appendChild(b);
    } else if(keys[i]!==mode && badge){
      badge.remove();
    }
  });
}

