/* ==========================================================
 * Gist 文件安全读取工具（解决 >1MB 文件被 API 截断问题）
 * ========================================================== */

/**
 * 安全获取 Gist 文件的完整内容
 * GitHub Gist API 对超过 1MB 的文件会截断 content 字段（返回空字符串）
 * 并设置 truncated: true，此时需通过 raw_url 获取完整内容
 *
 * @param {Object} file - gist.files[fileName] 对象
 * @param {string} token - GitHub Token（raw_url 需认证）
 * @returns {Promise<string|null>} 文件完整内容；获取失败返回 null
 */
async function fetchGistFileContent(file, token){
  if(!file) return null;

  // 如果 API 标记为截断，或 content 为空，通过 raw_url 获取完整内容
  if(file.truncated || !file.content){
    if(file.raw_url){
      // 尝试方式1：带 Authorization 头（可能触发 CORS 预检）
      try{
        const rawRes = await fetch(file.raw_url, {
          headers: { 'Authorization':`token ${token}` },
          cache: 'no-store'
        });
        if(rawRes.ok){
          return await rawRes.text();
        }
      }catch(e){
        console.warn('raw_url 方式1失败:', e.message);
      }
      // 尝试方式2：不带自定义头（避免CORS预检），依赖URL中的SHA访问
      try{
        const rawRes2 = await fetch(file.raw_url, {
          cache: 'no-store'
        });
        if(rawRes2.ok){
          return await rawRes2.text();
        }
      }catch(e){
        console.warn('raw_url 方式2失败:', e.message);
      }
      // 两种方式都失败
      if(file.truncated){
        console.warn('文件被截断且raw_url获取失败，跳过');
        return null;
      }
      return null;
    }
    return null;
  }

  // 正常情况：content 未被截断，直接使用
  return file.content;
}

/**
 * 安全 JSON 解析：捕获截断导致的解析错误，提供更有用的错误信息
 * @param {string} text - JSON 文本
 * @param {string} context - 上下文描述（如"用户数据"、"题库数据"）
 * @returns {Object} 解析后的对象
 */
function safeJsonParse(text, context){
  if(!text || typeof text !== 'string'){
    throw new Error(`${context||'数据'}为空，无法解析`);
  }
  try{
    return JSON.parse(text);
  }catch(e){
    const msg = e.message || '';
    const sizeKB = Math.round(text.length / 1024);
    // 截断类错误：内容不完整
    if(msg.includes('Unterminated') || msg.includes('Unexpected end') || msg.includes('Unexpected token')){
      throw new Error(`${context||'数据'}解析失败：内容可能被截断（${sizeKB}KB）。建议通过 raw_url 重新获取或检查网络连接。`);
    }
    throw new Error(`${context||'数据'}解析失败：${msg}（${sizeKB}KB）`);
  }
}

/* 上传：只上传当前用户+当前设备的数据（不含题目库） */
async function syncToCloud(){
  const token = localStorage.getItem('xuecheng_gist_token');
  if(!token) throw new Error('请先输入并保存 GitHub Token');
  
  // 上传当前用户+当前设备的数据
  const data = {
    userId: currentUserId,
    userName: currentUserName,
    deviceId: getDeviceId(),
    deviceLabel: getDeviceLabel(),
    users: await dbGetAll('users'),
    records: (await dbGetAll('records')).filter(r=>r.userId===currentUserId),
    wrongQuestions: (await dbGetAll('wrongQuestions')).filter(w=>w.userId===currentUserId),
    favorites: (await dbGetAll('favorites')).filter(f=>f.userId===currentUserId),
    notes: (await dbGetAll('notes')).filter(n=>n.userId===currentUserId),
    syncTime: new Date().toISOString()
  };
  
  const fileName = getUserGistFileName(currentUserId);
  const content = JSON.stringify(data);
  const gistId = getUserGistId(currentUserId);
  
  // 如果已有该用户的 Gist，尝试更新对应文件；否则创建新 Gist
  if(gistId){
    // 更新现有 Gist 中的对应用户文件
    const url = `https://api.github.com/gists/${gistId}`;
    const res = await fetch(url, {
      method:'PATCH',
      headers:{
        'Authorization':`token ${token}`,
        'Content-Type':'application/json',
        'Accept':'application/vnd.github.v3+json'
      },
      body: JSON.stringify({
        description:'学成选择题 · 用户数据备份',
        public:false,
        files:{ [fileName]:{ content } }
      })
    });
    if(!res.ok){
      const err = await res.json().catch(()=>({}));
      throw new Error(err.message||`HTTP ${res.status}`);
    }
  } else {
    // 首次上传：创建新 Gist
    const res = await fetch('https://api.github.com/gists', {
      method:'POST',
      headers:{
        'Authorization':`token ${token}`,
        'Content-Type':'application/json',
        'Accept':'application/vnd.github.v3+json'
      },
      body: JSON.stringify({
        description:'学成选择题 · 用户数据备份',
        public:false,
        files:{ [fileName]:{ content } }
      })
    });
    if(!res.ok){
      const err = await res.json().catch(()=>({}));
      throw new Error(err.message||`HTTP ${res.status}`);
    }
    const gist = await res.json();
    setUserGistId(currentUserId, gist.id);
  }
}

/* 下载：下载当前用户所有设备的数据并合并（不覆盖其他用户） */
async function syncFromCloud(){
  const token = localStorage.getItem('xuecheng_gist_token');
  if(!token) throw new Error('请先输入并保存 GitHub Token');
  
  const gistId = getUserGistId(currentUserId);
  if(!gistId) throw new Error('请先上传一次以创建云端备份');
  
  const res = await fetch(`https://api.github.com/gists/${gistId}`, {
    headers:{ 'Authorization':`token ${token}`, 'Accept':'application/vnd.github.v3+json' },
    cache: 'no-store'
  });
  if(!res.ok){
    const err = await res.json().catch(()=>({}));
    throw new Error(err.message||`HTTP ${res.status}`);
  }
  
  const gist = await res.json();
  
  // 遍历 Gist 中所有属于当前用户的文件（每个设备一个文件）
  const userPrefix = `user_${currentUserId}_`;
  const deviceFiles = Object.keys(gist.files || {}).filter(name => name.startsWith(userPrefix) && name.endsWith('_backup.json'));
  
  if(deviceFiles.length === 0){
    // 兼容旧格式文件名（无deviceId）
    const oldFile = gist.files && gist.files[`user_${currentUserId}_backup.json`];
    if(oldFile && oldFile.content){
      deviceFiles.push(`user_${currentUserId}_backup.json`);
    }
  }
  
  if(deviceFiles.length === 0) throw new Error('云端未找到当前用户的数据');
  
  let mergedCount = 0;
  let deviceList = [];
  const currentDevId = getDeviceId();
  
  for(const fileName of deviceFiles){
    const file = gist.files[fileName];
    if(!file) continue;
    
    const content = await fetchGistFileContent(file, token);
    if(!content) continue;
    
    const data = safeJsonParse(content, '用户数据');
    if(data.deviceLabel) deviceList.push(data.deviceLabel + (data.deviceId === currentDevId ? '（本机）' : ''));
    
    // 恢复用户列表
    if(data.users && Array.isArray(data.users)){
      const localUsers = await dbGetAll('users');
      for(const u of data.users){
        if(u && u.id && !localUsers.some(lu=>lu.id===u.id)){
          await dbAdd('users', u);
        }
      }
    }
    
    // 合并数据（put 操作，后写入的会覆盖同ID记录）
    for(const store of ['records','wrongQuestions','favorites','notes']){
      if(data[store] && Array.isArray(data[store])){
        for(const item of data[store]){
          if(item && item.id){
            item.userId = currentUserId;
            await dbAdd(store, item);
            mergedCount++;
          }
        }
      }
    }
  }
  
  await updateWrongBadge();
  await updateUserStreak();
  renderSettings();
  alert(`✅ 已合并「${currentUserName}」的云端数据\n来源设备：${deviceList.join('、')}\n合并记录：${mergedCount} 条`);
}

/* ==========================================================
 * 3.14 题库云同步（勘误补丁推送/拉取）
 * ========================================================== */
const QB_GIST_FILENAME = 'question_bank.json';
const QB_VERSION_KEY = 'question_bank_version';

/* 获取本地题库版本 */
function getLocalQuestionBankVersion(){
  return localStorage.getItem(QB_VERSION_KEY) || '';
}

/* 上传题库更新（上传所有题目：硬编码+IndexedDB合并后的最新版） */
async function uploadQuestionBankUpdate(){
  const token = localStorage.getItem('xuecheng_gist_token');
  if(!token) throw new Error('请先在云同步设置中配置 GitHub Token');
  const gistId = getUserGistId(currentUserId);
  if(!gistId) throw new Error('请先在云同步中上传一次用户数据以创建 Gist');

  // 上传合并后的完整题库（硬编码SAMPLE_QUESTIONS + IndexedDB导入题，后者优先）
  // 这样勘误修改过的题目（无论是在源码中还是IndexedDB中）都会被推送
  await reloadQuestions();
  const allQs = allQuestions;
  if(allQs.length === 0){
    throw new Error('本地没有题目，无需上传');
  }

  const version = new Date().toISOString();
  const data = {
    version,
    uploadedBy: getDeviceLabel(),
    totalCount: allQs.length,
    questions: allQs
  };
  const content = JSON.stringify(data);

  // 上传到已有 Gist 的 question_bank.json 文件
  const res = await fetch(`https://api.github.com/gists/${gistId}`, {
    method:'PATCH',
    headers:{
      'Authorization':`token ${token}`,
      'Content-Type':'application/json',
      'Accept':'application/vnd.github.v3+json'
    },
    body: JSON.stringify({
      description:'学成选择题 · 题库勘误补丁',
      files:{ [QB_GIST_FILENAME]:{ content } }
    })
  });
  if(!res.ok){
    const err = await res.json().catch(()=>({}));
    throw new Error(err.message||`HTTP ${res.status}`);
  }

  // 更新本地版本号
  localStorage.setItem(QB_VERSION_KEY, version);
  alert(`✅ 题库更新已上传\n题目总数：${allQs.length} 道\n版本：${version.slice(0,19).replace('T',' ')}\n\n其他设备下次打开应用时自动获取`);
}

/* 启动时检查题库是否有更新（横幅通知 + 自动同步） */
async function checkQuestionBankUpdate(){
  if(!qbAutoSyncEnabled) return; // 用户关闭了自动同步
  const token = localStorage.getItem('xuecheng_gist_token');
  if(!token) return;
  const gistId = getUserGistId(currentUserId);
  if(!gistId) return;

  // 防止重复检查
  if(window._qbChecking) return;
  window._qbChecking = true;

  try{
    showUpdateBanner('checking');

    const res = await fetch(`https://api.github.com/gists/${gistId}`, {
      headers:{ 'Authorization':`token ${token}`, 'Accept':'application/vnd.github.v3+json' },
      cache: 'no-store'
    });
    if(!res.ok){
      showUpdateBanner('hidden');
      return;
    }

    const gist = await res.json();
    const file = gist.files && gist.files[QB_GIST_FILENAME];
    if(!file){
      showUpdateBanner('hidden');
      return;
    }

    const content = await fetchGistFileContent(file, token);
    if(!content){
      showUpdateBanner('hidden');
      return;
    }

    const cloudData = safeJsonParse(content, '题库数据');
    const cloudVersion = cloudData.version || '';
    const localVersion = getLocalQuestionBankVersion();

    // 版本相同则静默隐藏
    if(cloudVersion === localVersion){
      showUpdateBanner('hidden');
      return;
    }

    // 发现新版本
    const questions = cloudData.questions || [];
    const totalCount = questions.length;
    const versionShort = (cloudVersion || '').slice(0,19).replace('T',' ');
    showUpdateBanner('available', {
      sub: `v${localVersion?'→'+versionShort:versionShort} · ${totalCount} 道题目 · 正在自动同步`
    });

    // 短暂延迟后开始同步
    await new Promise(r=>setTimeout(r, 600));

    // 开始下载合并
    showUpdateBanner('syncing', {
      sub: `下载并合并 ${totalCount} 道更新题目`,
      progress: 10
    });

    let updatedCount = 0;
    const batchSize = Math.max(1, Math.ceil(totalCount / 10));
    for(let i=0; i<questions.length; i++){
      const q = questions[i];
      if(q && q.id){
        await dbAdd('questions', q);
        updatedCount++;
      }
      // 每 batchSize 道更新一次进度
      if(i % batchSize === 0 || i === questions.length - 1){
        const pct = Math.round(((i+1)/totalCount) * 100);
        showUpdateBanner('syncing', {
          sub: `正在合并 ${i+1}/${totalCount} 道题目`,
          progress: pct
        });
      }
    }

    // 更新本地版本号
    localStorage.setItem(QB_VERSION_KEY, cloudVersion);

    // 重新加载题目
    await reloadQuestions();

    // 显示成功
    showUpdateBanner('success', {
      title: '题库已更新',
      sub: `已同步 ${updatedCount} 道题目 · 版本 ${versionShort}`
    });
  }catch(e){
    console.warn('题库更新检查失败', e);
    showUpdateBanner('error', {
      sub: e.message || '请检查网络后稍后重试'
    });
  }finally{
    window._qbChecking = false;
  }
}

/* ==========================================================
 * 3.15 共享解析云同步（多用户多设备）
 * ========================================================== */
const SHARED_NOTES_FILENAME = 'shared_notes.json';
const SHARED_NOTES_VERSION_KEY = 'shared_notes_version';
const SHARED_NOTES_CHUNK_PREFIX = 'shared_notes_';
const SHARED_NOTES_CHUNK_MAX_BYTES = 500000; // 500KB 安全阈值（含JSON包装后仍 <1MB，避免GitHub API截断）

/* 计算 UTF-8 编码后的字节长度 */
function getUtf8ByteLength(str){
  try{ return new TextEncoder().encode(str).length; }
  catch(e){ return str.length * 3; } // 降级估算（中文字符最多3字节）
}

/* 将解析数组按字节大小分块，每块不超过 maxBytes */
function splitNotesIntoChunks(notes, maxBytes){
  const chunks = [];
  let currentChunk = [];
  let currentSize = 0;
  for(const note of notes){
    const noteSize = getUtf8ByteLength(JSON.stringify(note));
    // 单条解析本身超限时，仍放入独立分块（无法再分割）
    if(currentSize + noteSize > maxBytes && currentChunk.length > 0){
      chunks.push(currentChunk);
      currentChunk = [];
      currentSize = 0;
    }
    currentChunk.push(note);
    currentSize += noteSize;
  }
  if(currentChunk.length > 0) chunks.push(currentChunk);
  return chunks;
}

/* 从 Gist 下载共享解析（自动处理分块格式）
 * 返回 { notes: [], version: '' } 或 null
 */
async function downloadSharedNotesFromGist(gist, token){
  const mainFile = gist.files && gist.files[SHARED_NOTES_FILENAME];
  if(!mainFile) return null;

  const mainContent = await fetchGistFileContent(mainFile, token);
  if(!mainContent) return null;

  const mainData = safeJsonParse(mainContent, '共享解析');

  // 非分块格式：直接返回
  if(!mainData.chunked){
    return { notes: mainData.notes || [], version: mainData.version || '' };
  }

  // 分块格式：读取所有分块并合并
  const chunkCount = mainData.chunkCount || 0;
  const allNotes = [];
  const failedChunks = [];
  for(let i = 1; i <= chunkCount; i++){
    const chunkFileName = `${SHARED_NOTES_CHUNK_PREFIX}${i}.json`;
    const chunkFile = gist.files && gist.files[chunkFileName];
    if(!chunkFile){
      failedChunks.push(i);
      continue;
    }
    const chunkContent = await fetchGistFileContent(chunkFile, token);
    if(!chunkContent){
      failedChunks.push(i);
      continue;
    }
    const chunkData = safeJsonParse(chunkContent, `共享解析分块${i}`);
    if(chunkData.notes && Array.isArray(chunkData.notes)){
      allNotes.push(...chunkData.notes);
    }
  }
  if(failedChunks.length > 0){
    console.warn(`⚠️ 共享解析有 ${failedChunks.length} 个分块读取失败: 分块${failedChunks.join(', ')}`);
    console.warn(`  成功读取 ${allNotes.length} 条解析，但可能缺少部分数据`);
  }
  return { notes: allNotes, version: mainData.version || '' };
}

/* 一键同步共享解析：上传本地解析 + 下载云端全量解析并合并
 * 使用独立的共享 Gist（所有用户共用），与个人数据 Gist 分离
 * 首次同步时自动创建共享 Gist，后续用户只需输入同一个 Gist ID
 */
async function syncSharedNotes(){
  const token = localStorage.getItem('xuecheng_gist_token');
  if(!token) throw new Error('请先在云同步设置中配置 GitHub Token');

  let gistId = getSharedGistId();
  let newlyCreatedGistId = null;

  // 收集本地所有解析
  const localNotes = await dbGetAll('notes');

  // 首次同步：如果没有共享 Gist ID，创建一个新的共享 Gist
  if(!gistId){
    const newVersion = new Date().toISOString();
    const initialContent = JSON.stringify({ version: newVersion, totalCount: 0, notes: [] });
    const createRes = await fetch('https://api.github.com/gists', {
      method:'POST',
      headers:{
        'Authorization':`token ${token}`,
        'Content-Type':'application/json',
        'Accept':'application/vnd.github.v3+json'
      },
      body: JSON.stringify({
        description:'学成选择题 · 共享解析池（多用户多设备）',
        public:false,
        files:{ [SHARED_NOTES_FILENAME]:{ content: initialContent } }
      })
    });
    if(!createRes.ok){
      const err = await createRes.json().catch(()=>({}));
      throw new Error(err.message||`创建共享Gist失败: HTTP ${createRes.status}`);
    }
    const newGist = await createRes.json();
    gistId = newGist.id;
    setSharedGistId(gistId);
    newlyCreatedGistId = gistId;
    // 提示用户把此 ID 分享给其他设备/用户
    showSyncToast(`✅ 已创建共享解析池，请将 Gist ID 分享给其他设备/用户`, 'success');
  }

  // 下载云端现有数据
  const res = await fetch(`https://api.github.com/gists/${gistId}`, {
    headers:{ 'Authorization':`token ${token}`, 'Accept':'application/vnd.github.v3+json' },
    cache: 'no-store'  // 防止浏览器缓存旧响应
  });
  if(!res.ok) throw new Error(`下载失败: HTTP ${res.status}`);

  const gist = await res.json();
  
  // 下载云端解析（自动处理分块格式）
  // 【Bug修复】下载失败时必须中止，绝不能用空数据覆盖云端
  let cloudNotes = [];
  let cloudVersion = '';
  const cloudResult = await downloadSharedNotesFromGist(gist, token);
  if(cloudResult){
    cloudNotes = cloudResult.notes;
    cloudVersion = cloudResult.version;
  } else {
    // shared_notes.json 不存在或内容获取失败 → 中止同步，防止数据覆盖
    throw new Error('云端解析文件不存在或读取失败（可能Gist ID指向了错误的Gist），已中止同步以防数据覆盖');
  }

  // 合并：本地 + 云端，按 ID 去重，按 lastModified 时间戳判断新旧
  const noteMap = new Map();
  // 先放入云端数据
  cloudNotes.forEach(n=>{ if(n && n.id) noteMap.set(n.id, n); });
  // 用本地数据覆盖：仅当本地版本更新时才覆盖
  localNotes.forEach(n=>{
    if(!n || !n.id) return;
    const existing = noteMap.get(n.id);
    if(!existing){
      noteMap.set(n.id, n);
    } else {
      // 比较 lastModified 时间戳，本地更新则覆盖
      const localTime = n.lastModified || n.createdDate || '';
      const cloudTime = existing.lastModified || existing.createdDate || '';
      if(localTime >= cloudTime){
        noteMap.set(n.id, n);
      }
    }
  });

  const mergedNotes = Array.from(noteMap.values());
  const newVersion = new Date().toISOString();

  // 统计
  const beforeCount = cloudNotes.length;
  const afterCount = mergedNotes.length;
  const newFromLocal = localNotes.filter(n => !cloudNotes.some(c => c.id === n.id)).length;
  const newFromCloud = cloudNotes.filter(n => !localNotes.some(l => l.id === n.id)).length;

  // 上传合并后的全量数据
  // 【关键修复】分块模式下逐块上传，避免单次请求 payload 过大被 GitHub 拒绝
  const mergedContent = JSON.stringify({ version: newVersion, totalCount: mergedNotes.length, notes: mergedNotes });
  const mergedBytes = getUtf8ByteLength(mergedContent);

  if(mergedBytes <= SHARED_NOTES_CHUNK_MAX_BYTES){
    // 非分块模式：单个文件一次上传
    const filesPayload = {};
    filesPayload[SHARED_NOTES_FILENAME] = { content: mergedContent };
    for(let i = 1; i <= 20; i++){
      const chunkName = `${SHARED_NOTES_CHUNK_PREFIX}${i}.json`;
      if(gist.files && gist.files[chunkName]){
        filesPayload[chunkName] = null;
      }
    }
    const uploadRes = await fetch(`https://api.github.com/gists/${gistId}`, {
      method:'PATCH',
      headers:{
        'Authorization':`token ${token}`,
        'Content-Type':'application/json',
        'Accept':'application/vnd.github.v3+json'
      },
      body: JSON.stringify({
        description:'学成选择题 · 共享解析',
        files: filesPayload
      })
    });
    if(!uploadRes.ok){
      const err = await uploadRes.json().catch(()=>({}));
      throw new Error(err.message||`上传失败: HTTP ${uploadRes.status}`);
    }
  } else {
    // 分块模式：逐块上传，每次只上传一个分块文件
    const chunks = splitNotesIntoChunks(mergedNotes, SHARED_NOTES_CHUNK_MAX_BYTES);

    // Step 1: 上传主文件（元数据）+ 第一个分块
    const step1Payload = {};
    step1Payload[SHARED_NOTES_FILENAME] = {
      content: JSON.stringify({ version: newVersion, chunked: true, chunkCount: chunks.length, totalNotes: mergedNotes.length })
    };
    const chunk1Name = `${SHARED_NOTES_CHUNK_PREFIX}1.json`;
    step1Payload[chunk1Name] = {
      content: JSON.stringify({ chunkIndex: 1, notes: chunks[0] })
    };
    const step1Res = await fetch(`https://api.github.com/gists/${gistId}`, {
      method:'PATCH',
      headers:{
        'Authorization':`token ${token}`,
        'Content-Type':'application/json',
        'Accept':'application/vnd.github.v3+json'
      },
      body: JSON.stringify({ description:'学成选择题 · 共享解析', files: step1Payload })
    });
    if(!step1Res.ok){
      const err = await step1Res.json().catch(()=>({}));
      throw new Error(err.message||`上传分块1失败: HTTP ${step1Res.status}`);
    }

    // Step 2: 逐个上传剩余分块
    for(let i = 1; i < chunks.length; i++){
      const chunkName = `${SHARED_NOTES_CHUNK_PREFIX}${i + 1}.json`;
      const chunkPayload = {};
      chunkPayload[chunkName] = {
        content: JSON.stringify({ chunkIndex: i + 1, notes: chunks[i] })
      };
      const chunkRes = await fetch(`https://api.github.com/gists/${gistId}`, {
        method:'PATCH',
        headers:{
          'Authorization':`token ${token}`,
          'Content-Type':'application/json',
          'Accept':'application/vnd.github.v3+json'
        },
        body: JSON.stringify({ files: chunkPayload })
      });
      if(!chunkRes.ok){
        const err = await chunkRes.json().catch(()=>({}));
        throw new Error(err.message||`上传分块${i+1}失败: HTTP ${chunkRes.status}`);
      }
    }

    // Step 3: 清理多余的旧分块文件
    const cleanupPayload = {};
    for(let i = chunks.length + 1; i <= 20; i++){
      const chunkName = `${SHARED_NOTES_CHUNK_PREFIX}${i}.json`;
      if(gist.files && gist.files[chunkName]){
        cleanupPayload[chunkName] = null;
      }
    }
    if(Object.keys(cleanupPayload).length > 0){
      await fetch(`https://api.github.com/gists/${gistId}`, {
        method:'PATCH',
        headers:{
          'Authorization':`token ${token}`,
          'Content-Type':'application/json',
          'Accept':'application/vnd.github.v3+json'
        },
        body: JSON.stringify({ files: cleanupPayload })
      });
    }
  }

  // 将云端其他用户的解析写入本地 IndexedDB
  // 【改进】不仅下载本地不存在的解析，还更新云端较新版本的解析
  let downloadedCount = 0;
  let updatedCount = 0;
  for(const n of cloudNotes){
    if(n && n.id){
      const localNote = localNotes.find(l => l.id === n.id);
      if(!localNote){
        // 本地不存在的解析，直接写入
        await dbAdd('notes', n);
        downloadedCount++;
      } else {
        // 本地已存在，比较时间戳，云端更新则覆盖本地
        const cloudTime = n.lastModified || n.createdDate || '';
        const localTime = localNote.lastModified || localNote.createdDate || '';
        if(cloudTime > localTime){
          await dbAdd('notes', n);
          updatedCount++;
        }
      }
    }
  }

  // 更新本地版本号
  localStorage.setItem(SHARED_NOTES_VERSION_KEY, newVersion);

  return {
    uploaded: localNotes.length,
    newFromLocal,
    newFromCloud,
    updatedFromCloud: updatedCount,
    totalMerged: mergedNotes.length,
    sharedGistId: newlyCreatedGistId
  };
}

/* 启动时静默检查共享解析更新（使用共享 Gist ID） */
async function checkSharedNotesUpdate(){
  const token = localStorage.getItem('xuecheng_gist_token');
  if(!token) return;
  const gistId = getSharedGistId();
  if(!gistId) return;

  try{
    const res = await fetch(`https://api.github.com/gists/${gistId}`, {
      headers:{ 'Authorization':`token ${token}`, 'Accept':'application/vnd.github.v3+json' },
      cache: 'no-store'
    });
    if(!res.ok) return;

    const gist = await res.json();

    // 下载云端解析（自动处理分块格式）
    const cloudResult = await downloadSharedNotesFromGist(gist, token);
    if(!cloudResult) return;

    const cloudVersion = cloudResult.version || '';
    const localVersion = localStorage.getItem(SHARED_NOTES_VERSION_KEY) || '';

    if(cloudVersion === localVersion) return;

    // 有更新，下载并合并（下载本地不存在的解析 + 更新云端较新版本的解析）
    const cloudNotes = cloudResult.notes || [];
    const localNotes = await dbGetAll('notes');
    let newCount = 0;
    let updateCount = 0;
    for(const n of cloudNotes){
      if(n && n.id){
        const localNote = localNotes.find(l => l.id === n.id);
        if(!localNote){
          await dbAdd('notes', n);
          newCount++;
        } else {
          // 比较时间戳，云端更新则覆盖本地
          const cloudTime = n.lastModified || n.createdDate || '';
          const localTime = localNote.lastModified || localNote.createdDate || '';
          if(cloudTime > localTime){
            await dbAdd('notes', n);
            updateCount++;
          }
        }
      }
    }

    localStorage.setItem(SHARED_NOTES_VERSION_KEY, cloudVersion);

    if(newCount > 0 || updateCount > 0){
      showSyncToast(`📝 获取 ${newCount} 条新解析，更新 ${updateCount} 条`, 'success');
      // 有新解析时刷新列表
      if(document.getElementById('panel-notes') && document.getElementById('panel-notes').classList.contains('active')){
        renderNotes();
      }
    }
  }catch(e){
    console.warn('共享解析更新检查失败', e);
    showSyncToast(`⚠️ 解析更新检查失败: ${e.message}`, 'error');
  }
}

/* 【新增】强制全量拉取云端解析（忽略版本号，下载全部云端解析并合并到本地）
 * 用于手动修复同步不一致问题
 */
async function forceDownloadSharedNotes(){
  const token = localStorage.getItem('xuecheng_gist_token');
  if(!token) throw new Error('请先配置 GitHub Token');
  const gistId = getSharedGistId();
  if(!gistId) throw new Error('未配置共享解析池 Gist ID');

  const res = await fetch(`https://api.github.com/gists/${gistId}`, {
    headers:{ 'Authorization':`token ${token}`, 'Accept':'application/vnd.github.v3+json' },
    cache: 'no-store'
  });
  if(!res.ok) throw new Error(`下载失败: HTTP ${res.status}`);

  const gist = await res.json();
  const cloudResult = await downloadSharedNotesFromGist(gist, token);
  if(!cloudResult){
    throw new Error('云端解析文件不存在或读取失败');
  }

  const cloudNotes = cloudResult.notes || [];
  const localNotes = await dbGetAll('notes');
  const localIds = new Set(localNotes.map(n=>n.id));

  let newCount = 0;
  let updateCount = 0;
  for(const n of cloudNotes){
    if(n && n.id){
      if(!localIds.has(n.id)){
        await dbAdd('notes', n);
        newCount++;
      } else {
        // 比较时间戳，云端更新则覆盖本地
        const local = localNotes.find(l=>l.id===n.id);
        const cloudTime = n.lastModified || n.createdDate || '';
        const localTime = (local && (local.lastModified || local.createdDate)) || '';
        if(cloudTime > localTime){
          await dbAdd('notes', n);
          updateCount++;
        }
      }
    }
  }

  localStorage.setItem(SHARED_NOTES_VERSION_KEY, cloudResult.version || '');
  return { newCount, updateCount, cloudTotal: cloudNotes.length };
}

/* 【新增】诊断共享解析同步状态（用户可见的详细信息）
 * 检查云端和本地的解析数量、Gist ID、版本号
 */
async function diagnoseSharedSync(){
  const token = localStorage.getItem('xuecheng_gist_token');
  const gistId = getSharedGistId();
  const localNotes = await dbGetAll('notes');
  const localVersion = localStorage.getItem(SHARED_NOTES_VERSION_KEY) || '无';

  let report = `📊 共享解析同步诊断\n\n`;
  report += `本地解析：${localNotes.length} 条\n`;
  report += `本地版本：${localVersion}\n`;
  report += `共享Gist ID：${gistId || '未配置'}\n`;
  report += `GitHub Token：${token ? '已配置' : '未配置'}\n\n`;

  if(!token){
    report += `⚠️ 未配置 GitHub Token，无法检查云端`;
    alert(report);
    return;
  }
  if(!gistId){
    report += `⚠️ 未配置共享 Gist ID\n\n请先在一台设备上点击「一键同步」创建共享池，然后将 Gist ID 复制到其他设备`;
    alert(report);
    return;
  }

  try{
    const res = await fetch(`https://api.github.com/gists/${gistId}`, {
      headers:{ 'Authorization':`token ${token}`, 'Accept':'application/vnd.github.v3+json' },
      cache: 'no-store'
    });
    if(!res.ok){
      report += `❌ 云端Gist访问失败: HTTP ${res.status}\n`;
      if(res.status === 404) report += `Gist ID 不存在或已被删除`;
      alert(report);
      return;
    }

    const gist = await res.json();

    // 【详细诊断】显示 Gist 中的所有文件信息
    const fileNames = Object.keys(gist.files || {});
    report += `云端Gist文件列表（${fileNames.length}个文件）：\n`;
    for(const fname of fileNames){
      const f = gist.files[fname];
      const sizeKB = f.size ? Math.round(f.size/1024) : 0;
      report += `  ${fname} (${sizeKB}KB${f.truncated ? ', 已截断!' : ''})\n`;
    }
    report += '\n';

    const cloudResult = await downloadSharedNotesFromGist(gist, token);
    if(!cloudResult){
      report += `❌ 云端解析文件不存在或读取失败\n`;
      report += `Gist中的文件: ${fileNames.join(', ')}`;
      alert(report);
      return;
    }

    const cloudNotes = cloudResult.notes || [];
    const cloudVersion = cloudResult.version || '无';
    const localIds = new Set(localNotes.map(n=>n.id));
    const cloudOnlyCount = cloudNotes.filter(n => !localIds.has(n.id)).length;

    report += `云端解析：${cloudNotes.length} 条\n`;
    report += `云端版本：${cloudVersion}\n`;
    report += `本地缺少：${cloudOnlyCount} 条\n\n`;

    if(cloudOnlyCount > 0){
      report += `⚠️ 本地缺少 ${cloudOnlyCount} 条云端解析\n`;
      report += `建议：点击「一键同步」或「强制拉取」来获取缺失解析`;
    } else if(cloudNotes.length === localNotes.length){
      report += `✅ 本地与云端解析数量一致，同步正常`;
    } else {
      report += `ℹ️ 本地比云端多 ${localNotes.length - cloudNotes.length} 条\n`;
      report += `建议：点击「一键同步」上传本地解析到云端`;
    }

    alert(report);
  }catch(e){
    report += `❌ 诊断失败: ${e.message}`;
    alert(report);
  }
}

