async function exportNotes(){
  const notes = (await dbGetAll('notes')).filter(n=>n.userId===currentUserId);
  if(notes.length===0){ alert('暂无解析笔记可导出'); return; }
  const blob = new Blob([JSON.stringify(notes, null, 2)], { type:'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `xuecheng_notes_${Date.now()}.json`;
  a.click();
  URL.revokeObjectURL(a.href);
}

async function importNotes(event){
  const file = event.target.files[0];
  if(!file) return;
  try{
    const text = await file.text();
    const data = JSON.parse(text);
    const arr = Array.isArray(data) ? data : [data];
    let count = 0;
    for(const n of arr){
      if(!n.id) n.id = `note_${currentUserId}_${n.questionId||'unknown'}_${Date.now()}_${count}`;
      n.userId = currentUserId;
      await dbAdd('notes', n);
      count++;
    }
    alert(`成功导入 ${count} 条笔记`);
    renderNotes();
  }catch(e){
    alert('导入失败：'+e.message);
  }
  event.target.value = '';
}

